import { PubSub } from 'graphql-subscriptions';
const pubsub = new PubSub();
export const resolvers = {
  Mutation: {
    post: (_, { text }) => { pubsub.publish('{{event_name}}', { onPost: { text } }); return { text }; }
  },
  Subscription: {
    onPost: { subscribe: () => pubsub.asyncIterator(['{{event_name}}']) }
  }
};
